)

# 1. Calculate the overall maximum movie year at the GRAPH level.
max_movie_year_data = GRAPH.CALCULATE(
    max_movie_year_val=MAX(Movie.year)
)

# 2. Filter ratings to include only those for movies from the max_movie_year.
# 3. Group by the movie year and then calculate the maximum stars.
result = GRAPH.Rating.WHERE(
    movie.year == max_movie_year_data.SINGULAR().max_movie_year_val
).GROUP_BY(
    most_recent_movie_year=movie.year # Group by the year
).CALCULATE(
    max_stars_for_recent_movie=MAX(stars)
)

total_balances_by_customer = checkings.CALCULATE(
    customer_id=custid,
    checking_balance=FLOAT(balance),
    saving_balance=FLOAT(account.saving.balance)
).WHERE(
    HAS(saving_balance) == 1
).CALCULATE(
    customer_id=customer_id,
    total_balance=checking_balance + saving_balance
).ORDER_BY(total_balance.ASC())

bike_trip_stats = trip.WHERE(
    bike_id == 636
).CALCULATE(
    total_duration = SUM(duration),
    max_duration = MAX(duration)
)

filtered_cities = cities.WHERE(
    (cities.temperatures.SINGULAR().mar < cities.temperatures.SINGULAR().jul) |
    (cities.temperatures.SINGULAR().mar > cities.temperatures.SINGULAR().oct)
).CALCULATE(
    city_name=city
)

makers_with_many_models = model_lists.PARTITION(
    name="maker_group",
    by=(car_maker.id, car_maker.fullname)
).CALCULATE(
    maker_id=car_maker.id,
    maker_fullname=car_maker.fullname,
    num_models=COUNT(model_lists)
).WHERE(
    num_models > 3
).CALCULATE(
    fullname=maker_fullname,
    id=maker_id
)

most_frequent_template_type = template.CALCULATE(
    dummy_one=1
).PARTITION(
    name="type_counts",
    by=template_type_code
).CALCULATE(
    template_type_code=template_type_code,
    num_templates=SUM(template.dummy_one)
).ORDER_BY(
    num_templates.DESC()
).TOP_K(1).CALCULATE(
    Template_Type_Code=template_type_code
)

result = vocal.WHERE(
    (vocal.band.firstname == "Solveig") &
    (vocal.song.title == "A Bar in Amsterdam")
).CALCULATE(
    vocal_type=type
)

result = people.WHERE(
    HAS(personfriends.person.WHERE(person.city == 'new york city')) == 1
).CALCULATE(
    person_name=name
)

result = students.WHERE(
    # Check if there is any voting record in the entire 'voting_records' collection
    # where the election_cycle is 'Spring' AND the 'treasurer_vote' (which is the StuID of the student who received the vote)
    # matches the 'stuid' of the current student being evaluated from the 'students' collection.
    HAS(GRAPH.voting_records.WHERE(
        (GRAPH.voting_records.election_cycle == 'Spring') &
        (GRAPH.voting_records.treasurer_vote == stuid)
    )) == 1
).CALCULATE(
    advisor_id=advisor # Select the advisor for the matched students
).PARTITION(name="unique_advisors_found", by=advisor_id).CALCULATE(
    advisor_id=advisor_id # Return only distinct advisor IDs
)

result = GreaterManchesterCrime.PARTITION(
    name="location_stats",
    by=GreaterManchesterCrime.Location
).CALCULATE(
    crime_location=FIRST(GreaterManchesterCrime.Location),
    total_crimes=COUNT(GreaterManchesterCrime.CrimeID)
).TOP_K(1, by=total_crimes.DESC()).CALCULATE(
    Location=crime_location
)

vldb_citations = GRAPH.CALCULATE(
    total_citations=DEFAULT_TO(SUM(academic.conferences.WHERE(name == 'VLDB').publications.citation_num), 0)
)

crime_rate_eden_street = GreaterManchesterCrime.WHERE(
    CONTAINS(Location, "Eden Street")
).CALCULATE(
    crime_count=COUNT()
)

largest_capacity_plant = GeoNuclearData.nuclear_power_plants.CALCULATE(
    numeric_capacity=DEFAULT_TO(FLOAT(Capacity), 0.0)
).TOP_K(1, by=numeric_capacity.DESC()).CALCULATE(
    Name=Name
)

most_prosecuted_crime_type = greatermanchestercrimes.WHERE(
    outcome == "Awaiting court outcome"
).CALCULATE(
    crime_type=type
).PARTITION(
    name="crime_groups",
    by=(crime_type)
).CALCULATE(
    crime_type=crime_type,
    total_prosecution_cases=COUNT(crime_groups)
).TOP_K(1, by=total_prosecution_cases.DESC())
